#include <Arduino.h>

// -------- Motor specifications --------
const float STEP_ANGLE = 1.8;
const int STEPS_PER_REV = (int)(360.0 / STEP_ANGLE + 0.5);

// -------- Pins --------
const byte MOTOR_PINS[4] = {8, 9, 10, 11};
const byte POT_PIN = A0;
const byte BUTTON_PIN = 2;

// -------- Timing --------
const int MIN_DELAY_MS = 2;
const int MAX_DELAY_MS = 20;
const unsigned long PAUSE_MS = 1000;
const unsigned long DEBOUNCE_MS = 40;

// Full-step sequence for bipolar stepper + L298
const byte STEP_SEQUENCE[4][4] = {
  {HIGH, LOW,  HIGH, LOW },
  {LOW,  HIGH, HIGH, LOW },
  {LOW,  HIGH, LOW,  HIGH},
  {HIGH, LOW,  LOW,  HIGH}
};

// -------- State --------
int direction = 1;        // +1: CW, -1: CCW
int stepIndex = 0;

bool lastButtonReading = HIGH;
bool stableButtonState = HIGH;
unsigned long lastDebounceTime = 0;

// -------- Button with debounce --------
void checkButton() {
  bool reading = digitalRead(BUTTON_PIN);

  if (reading != lastButtonReading) {
    lastDebounceTime = millis();
  }

  if (millis() - lastDebounceTime >= DEBOUNCE_MS) {
    if (reading != stableButtonState) {
      stableButtonState = reading;

      // Toggle only when button is pressed
      if (stableButtonState == LOW) {
        direction = -direction;
      }
    }
  }

  lastButtonReading = reading;
}

// -------- Apply one motor step --------
void motorStep() {
  if (direction == 1) {
    stepIndex = (stepIndex + 1) % 4;
  } else {
    stepIndex = (stepIndex + 3) % 4;
  }

  for (int pin = 0; pin < 4; pin++) {
    digitalWrite(MOTOR_PINS[pin],
                 STEP_SEQUENCE[stepIndex][pin]);
  }
}

// -------- Rotate 360 degrees --------
void rotateOneRevolution() {
  for (int step = 0; step < STEPS_PER_REV; step++) {
    checkButton();

    int potValue = analogRead(POT_PIN);
    int stepDelay = map(potValue, 0, 1023,
                        MAX_DELAY_MS, MIN_DELAY_MS);

    motorStep();
    delay(stepDelay);
  }
}

// -------- Pause while checking button --------
void pauseMotor(unsigned long duration) {
  unsigned long startTime = millis();

  while (millis() - startTime < duration) {
    checkButton();
    delay(1);
  }
}

void setup() {
  for (int pin = 0; pin < 4; pin++) {
    pinMode(MOTOR_PINS[pin], OUTPUT);
    digitalWrite(MOTOR_PINS[pin], LOW);
  }

  pinMode(POT_PIN, INPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void loop() {
  // 1. One complete revolution (initially CW)
  rotateOneRevolution();

  // 2. Wait one second
  pauseMotor(PAUSE_MS);

  // 3. Reverse direction
  direction = -direction;

  // 4. One revolution in opposite direction
  rotateOneRevolution();

  // Restore initial direction for next cycle
  direction = -direction;
}
